package edu.uow.csit314.idp.controller;
import edu.uow.csit314.idp.entity.*;
import edu.uow.csit314.idp.repository.*;
import edu.uow.csit314.idp.dto.PlatformDtos.*;
import jakarta.servlet.http.HttpSession;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import static edu.uow.csit314.idp.controller.AuthenticationController.error;
@Service @Transactional
public class UserManagementController {
 private final UserAccountRepository users;private final UserProfileRepository profiles;private final AuthenticationController auth;private final PasswordService passwords;private final ActivityController activity;
 public UserManagementController(UserAccountRepository u,UserProfileRepository p,AuthenticationController a,PasswordService pw,ActivityController e){users=u;profiles=p;auth=a;passwords=pw;activity=e;}
 public List<ProfileResponse> profiles(String query,HttpSession s){auth.require(s,Role.USER_ADMIN);String q=query==null?"":query.toLowerCase();return profiles.findAllByOrderByIdDesc().stream().filter(p->(p.getName()+" "+p.getEmail()+" "+p.getStatus()).toLowerCase().contains(q)).map(p->DtoMapper.profile(p,users.findByProfileId(p.getId()).map(UserAccount::getId).orElse(null))).toList();}
 public ProfileResponse profile(Long id,HttpSession s){auth.require(s,Role.USER_ADMIN);UserProfile p=profiles.findById(id).orElseThrow(()->error(404,"Profile not found"));return DtoMapper.profile(p,users.findByProfileId(id).map(UserAccount::getId).orElse(null));}
 public ProfileResponse saveProfile(Long id,ProfileRequest d,HttpSession s){UserAccount admin=auth.require(s,Role.USER_ADMIN);UserProfile p=id==null?new UserProfile():profiles.findById(id).orElseThrow(()->error(404,"Profile not found"));p.setName(d.name().trim());p.setEmail(d.email().trim().toLowerCase());p.setPhone(d.phone());p.setAddress(d.address());p.setBio(d.bio());if(id==null)p.setStatus("ACTIVE");profiles.save(p);activity.record(id==null?"profile_created":"profile_updated",admin,null);return DtoMapper.profile(p,users.findByProfileId(p.getId()).map(UserAccount::getId).orElse(null));}
 public void deleteProfile(Long id,HttpSession s){UserAccount admin=auth.require(s,Role.USER_ADMIN);UserProfile p=profiles.findById(id).orElseThrow(()->error(404,"Profile not found"));users.findByProfileId(id).ifPresent(u->{u.setProfile(null);users.saveAndFlush(u);});profiles.delete(p);activity.record("profile_deleted",admin,null);}
 public ProfileResponse suspendProfile(Long id,HttpSession s){UserAccount admin=auth.require(s,Role.USER_ADMIN);UserProfile p=profiles.findById(id).orElseThrow(()->error(404,"Profile not found"));p.setStatus("ACTIVE".equals(p.getStatus())?"SUSPENDED":"ACTIVE");activity.record("profile_status_changed",admin,null);return DtoMapper.profile(p,users.findByProfileId(id).map(UserAccount::getId).orElse(null));}
 public List<AccountResponse> accounts(String query,HttpSession s){auth.require(s,Role.USER_ADMIN);String q=query==null?"":query.toLowerCase();return users.findAllByOrderByIdAsc().stream().filter(u->(u.getEmail()+" "+(u.getProfile()==null?"":u.getProfile().getName())+" "+u.getRoles()).toLowerCase().contains(q)).map(u->DtoMapper.account(u,u.getDefaultRole())).toList();}
 public AccountResponse account(Long id,HttpSession s){auth.require(s,Role.USER_ADMIN);UserAccount u=users.findById(id).orElseThrow(()->error(404,"Account not found"));return DtoMapper.account(u,u.getDefaultRole());}
 public AccountResponse saveAccount(Long id,AccountRequest d,HttpSession s){UserAccount admin=auth.require(s,Role.USER_ADMIN);UserAccount u=id==null?new UserAccount():users.findById(id).orElseThrow(()->error(404,"Account not found"));String email=d.email().trim().toLowerCase();users.findByEmailIgnoreCase(email).filter(other->!other.getId().equals(id)).ifPresent(other->{throw error(409,"Email already registered");});Set<Role> assigned=d.roles()==null?new HashSet<>():new HashSet<>(d.roles());assigned.add(d.defaultRole());if(id!=null&&id.equals(admin.getId())&&!assigned.contains(Role.USER_ADMIN))throw error(400,"You cannot remove your own User Admin access");if(id==null){if(d.password()==null||d.password().isBlank())throw error(400,"Password is required");u.setPasswordHash(passwords.encode(d.password()));u.setStatus("ACTIVE");if(d.profileId()!=null){UserProfile p=profiles.findById(d.profileId()).orElseThrow(()->error(404,"Profile not found"));if(users.findByProfileId(p.getId()).isPresent())throw error(409,"Profile already has an account");u.setProfile(p);}else{if(d.name()==null||d.name().isBlank())throw error(400,"Enter a name or choose an existing profile");UserProfile p=new UserProfile();p.setName(d.name().trim());p.setEmail(email);p.setStatus("ACTIVE");u.setProfile(p);}}else if(d.password()!=null&&!d.password().isBlank()){u.setPasswordHash(passwords.encode(d.password()));u.revokeSessions();}if(id!=null&&(!assigned.equals(u.getRoles())||d.defaultRole()!=u.getDefaultRole()))u.revokeSessions();u.setEmail(email);u.setRoles(assigned);u.setDefaultRole(d.defaultRole());users.save(u);activity.record(id==null?"account_created":"account_updated",admin,null);return DtoMapper.account(u,u.getDefaultRole());}
 public AccountResponse suspendAccount(Long id,HttpSession s){UserAccount admin=auth.require(s,Role.USER_ADMIN);if(admin.getId().equals(id))throw error(400,"You cannot suspend your own account");UserAccount u=users.findById(id).orElseThrow(()->error(404,"Account not found"));u.setStatus(u.isActive()?"SUSPENDED":"ACTIVE");u.revokeSessions();activity.record("account_status_changed",admin,null);return DtoMapper.account(u,u.getDefaultRole());}
}
